# Parity test for the FLUX 3 text-encoder path against a tiny random-init
# transformers Qwen3VLForConditionalGeneration (fixture generated by
# tools/gen_fixtures_flux3_qwen.py, checked in).

if (!requireNamespace("torch", quietly = TRUE) || !torch::torch_is_installed()) {
  exit_file("torch not fully installed")
}
if (!requireNamespace("safetensors", quietly = TRUE)) {
  exit_file("safetensors not installed")
}

library(diffuseR)

fixture_path <- system.file("tinytest", "fixtures", "flux3_qwen.safetensors",
  package = "diffuseR")
if (fixture_path == "") fixture_path <- "fixtures/flux3_qwen.safetensors"
ckpt_dir <- system.file("tinytest", "fixtures", "flux3_qwen_tiny_ckpt",
  package = "diffuseR")
if (ckpt_dir == "") ckpt_dir <- "fixtures/flux3_qwen_tiny_ckpt"
if (!file.exists(fixture_path) || !dir.exists(ckpt_dir)) {
  exit_file("flux3 qwen fixtures missing")
}

fx <- safetensors::safe_load_file(fixture_path, framework = "torch")

max_abs_diff <- function(a, b) {
  as.numeric(torch::torch_max(torch::torch_abs(
    a$to(dtype = torch::torch_float32()) - b$to(dtype = torch::torch_float32())
  )))
}

# The Qwen3-VL layout loads (text model only, vision tower skipped) with
# the nested text config, including rope_theta under rope_parameters
model <- load_qwen3_text_encoder(ckpt_dir, device = "cpu",
  dtype = "float32", verbose = FALSE)
expect_equal(model$rope_theta, 5e6)
expect_equal(length(model$model$layers), 4L)

ids <- fx$input_ids$to(dtype = torch::torch_long()) + 1L
mask <- fx$attention_mask$to(dtype = torch::torch_long())
positions <- as.integer(as.array(fx$position_ids))
expect_equal(positions, c(0:8, 1L, 1L, 1L))

states <- torch::with_no_grad(model(ids, attention_mask = mask,
  out_layers = c(1L, 2L, 4L), position_ids = positions))
stacked <- torch::torch_cat(states, dim = -1L)
expect_equal(as.integer(stacked$shape), as.integer(fx$stacked$shape))
# Padding states included: the transformer attends to them
expect_true(max_abs_diff(stacked, fx$stacked) < 1e-5)

# Default positions (0..S-1) change the padding states only
states_default <- torch::with_no_grad(model(ids, attention_mask = mask,
  out_layers = c(1L, 2L, 4L)))
default <- torch::torch_cat(states_default, dim = -1L)
expect_true(max_abs_diff(default[, 1:9, ], fx$stacked[, 1:9, ]) < 1e-5)
expect_true(max_abs_diff(default[, 10:12, ], fx$stacked[, 10:12, ]) > 1e-4)

# Window: rounded up to the pad multiple, capped, pads at position 1
win <- diffuseR:::.flux3_text_window(1:9, 0L, 8192L, 4L)
expect_equal(length(win$ids), 12L)
expect_equal(win$mask, c(rep(1L, 9), 0L, 0L, 0L))
expect_equal(win$positions, c(0:8, 1L, 1L, 1L))
win <- diffuseR:::.flux3_text_window(1:100, 0L, 90L, 80L)
expect_equal(length(win$ids), 90L)
expect_equal(sum(win$mask), 90L)
